Manipulación de precios.ejemplo:
// Backend seguro: ignorar price del cliente y recalcular desde BD
const items = await db.products.findByIds(req.body.items.map(i => i.sku));
const totalCents = req.body.items.reduce((sum, item) => {
  if (!Number.isInteger(item.qty) || item.qty <= 0) throw new BadRequest();
  const product = items.find(p => p.sku === item.sku);
  return sum + product.priceCents * item.qty;
}, 0);

